create extension if not exists pgcrypto;
create type public.app_role as enum ('business_owner','support_admin','super_admin');
create type public.appointment_status as enum ('agendado','confirmado','finalizado','nao_compareceu','cancelado');
create table public.businesses(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,owner_name text,whatsapp text,timezone text not null default 'America/Sao_Paulo',daily_capacity int not null default 0 check(daily_capacity>=0),trial_started_at timestamptz not null default now(),trial_ends_at timestamptz not null default now()+interval '7 days',subscription_status text not null default 'trial',created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,avatar_url text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.memberships(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role public.app_role not null default 'business_owner',created_at timestamptz default now(),unique(business_id,user_id));
create table public.services(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,price numeric(12,2) not null default 0 check(price>=0),duration_minutes int not null default 30,active boolean not null default true,created_at timestamptz default now());
create table public.professionals(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,active boolean not null default true,created_at timestamptz default now());
create table public.customers(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,whatsapp text,created_at timestamptz default now());
create table public.appointments(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,customer_id uuid not null references public.customers(id),service_id uuid not null references public.services(id),professional_id uuid references public.professionals(id),appointment_date date not null,start_time time not null,status public.appointment_status not null default 'agendado',final_value numeric(12,2),completed_at timestamptz,created_at timestamptz default now());
create table public.daily_capacity(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,date date not null,capacity int not null check(capacity>=0),unique(business_id,date));
create table public.transactions(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,appointment_id uuid references public.appointments(id),type text not null check(type in('revenue','expense')),amount numeric(12,2) not null check(amount>=0),occurred_at timestamptz default now(),created_at timestamptz default now());
create table public.monthly_goals(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,year int not null,month int not null check(month between 1 and 12),target_value numeric(12,2) not null,created_at timestamptz default now(),unique(business_id,year,month));
create table public.reports(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,report_date date not null,appointments_total int default 0,attended_total int default 0,canceled_total int default 0,no_show_total int default 0,revenue_total numeric(12,2) default 0,services_total int default 0,average_ticket numeric(12,2) default 0,created_at timestamptz default now(),unique(business_id,report_date));
create table public.subscriptions(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,provider text,external_customer_id text,external_subscription_id text,plan_name text,status text default 'pending',started_at timestamptz,next_billing_at timestamptz,created_at timestamptz default now());
create table public.payment_events(id uuid primary key default gen_random_uuid(),business_id uuid references public.businesses(id) on delete set null,provider text,event_type text,external_event_id text,payload jsonb,created_at timestamptz default now(),unique(provider,external_event_id));
create table public.audit_logs(id uuid primary key default gen_random_uuid(),business_id uuid references public.businesses(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,action text not null,entity_type text,entity_id uuid,metadata jsonb,created_at timestamptz default now());
create index on public.memberships(user_id); create index on public.memberships(business_id); create index on public.appointments(business_id,appointment_date,start_time); create index on public.customers(business_id); create index on public.services(business_id); create index on public.professionals(business_id);
create or replace function public.is_member(b uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.business_id=b and m.user_id=(select auth.uid()))$$;
create or replace function public.has_role(r public.app_role) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.user_id=(select auth.uid()) and m.role=r)$$;
revoke execute on function public.is_member(uuid) from public,anon; grant execute on function public.is_member(uuid) to authenticated;
revoke execute on function public.has_role(public.app_role) from public,anon; grant execute on function public.has_role(public.app_role) to authenticated;
do $$ declare t text; begin foreach t in array array['businesses','profiles','memberships','services','professionals','customers','appointments','daily_capacity','transactions','monthly_goals','reports','subscriptions','payment_events','audit_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy profiles_own on public.profiles for all to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy business_member on public.businesses for select to authenticated using(public.is_member(id) or public.has_role('support_admin') or public.has_role('super_admin'));
create policy memberships_self on public.memberships for select to authenticated using(user_id=(select auth.uid()) or public.has_role('support_admin') or public.has_role('super_admin'));
create policy services_member on public.services for all to authenticated using(public.is_member(business_id)) with check(public.is_member(business_id));
create policy professionals_member on public.professionals for all to authenticated using(public.is_member(business_id)) with check(public.is_member(business_id));
create policy customers_member on public.customers for all to authenticated using(public.is_member(business_id)) with check(public.is_member(business_id));
create policy appointments_member on public.appointments for all to authenticated using(public.is_member(business_id)) with check(public.is_member(business_id));
create policy capacity_member on public.daily_capacity for all to authenticated using(public.is_member(business_id)) with check(public.is_member(business_id));
create policy transactions_member on public.transactions for all to authenticated using(public.is_member(business_id)) with check(public.is_member(business_id));
create policy goals_member on public.monthly_goals for all to authenticated using(public.is_member(business_id)) with check(public.is_member(business_id));
create policy reports_member on public.reports for select to authenticated using(public.is_member(business_id));
create policy subscriptions_member on public.subscriptions for select to authenticated using(public.is_member(business_id));
create policy payment_events_admin on public.payment_events for select to authenticated using(public.has_role('support_admin') or public.has_role('super_admin'));
create policy audit_member on public.audit_logs for select to authenticated using(public.is_member(business_id) or public.has_role('support_admin') or public.has_role('super_admin'));
